import Foundation

/// Reads the exact localized string resources embedded in the supplied build 2 IPA.
/// `Bundle.module` is generated by SwiftPM for the copied `.lproj` resources.
public enum Beans203Localization_2_0_3 {
    public static func string(forKey key: String, table: String? = nil) -> String {
        Bundle.module.localizedString(forKey: key, value: nil, table: table)
    }
}
